import numpy as np, pandas as pd
from io import StringIO
import pandas._libs.lib as lib

# Helper to record exceptions deterministically

def run_or_exc(fn):
    try:
        return ("ok", fn())
    except Exception as e:
        return ("exc", type(e).__name__, str(e))

records = []

def rec(name, val):
    records.append((name, val))

# 1) maybe_convert_numeric overflow scalar preserved? 
arr = np.array([1<<65], dtype=object)
rec('maybe_convert_numeric_overflow_pos', run_or_exc(lambda: lib.maybe_convert_numeric(arr, set(), coerce_numeric=False)))

arr = np.array([-(1<<65)], dtype=object)
rec('maybe_convert_numeric_overflow_neg', run_or_exc(lambda: lib.maybe_convert_numeric(arr, set(), coerce_numeric=False)))

# 2) string beyond range w/ coerce_numeric
arr = np.array([str(1<<65)], dtype=object)
rec('maybe_convert_numeric_overflow_str_coerce', run_or_exc(lambda: lib.maybe_convert_numeric(arr, set(), coerce_numeric=True)))

arr = np.array([f"-{1<<65}"], dtype=object)
rec('maybe_convert_numeric_overflow_neg_str_coerce_false', run_or_exc(lambda: lib.maybe_convert_numeric(arr, set(), coerce_numeric=False)))

# 3) read_csv parsing for large int+fraction w/out explicit dtype
csv = "value\n42\n18446744073709551616.5\n"  # 2**64 + 0.5

def parse_csv():
    df = pd.read_csv(StringIO(csv))
    s = df['value']
    v = s.values
    # reduce to a compact representation
    if hasattr(v, 'dtype'):
        return {'dtype': str(v.dtype), 'values': v.tolist()}
    return {'dtype': None, 'values': list(v)}
rec('read_csv_large_int_plus_half', run_or_exc(parse_csv))

# 4) to_numeric really large scalar should (pre-fix behavior) raise
# pick a large scalar; mirror report's 'really large' beyond int64 as string
big = str(1<<65)

def to_num():
    return pd.to_numeric(big, errors=None)
rec('to_numeric_large_string', run_or_exc(to_num))

# Output all records
probe_out = {k:v for k,v in records}
probe(probe_out)

